  const guideScope=state.docScope==='guides',certScope=state.docScope==='certification';
  const params=new URLSearchParams({q:$('#docSearch').value.trim(),scope:guideScope?'public':certScope?'all':state.docScope,category:guideScope?'Study Guides':$('#docFilter').value,product:$('#docProduct').value,version:$('#docVersion').value,language:$('#docLanguage').value});
