async function loadQuestions(){const language=$('#questionLanguage').value||state.user.questionLanguage||'pt-BR',summaryUrl=`/api/v2/question-bank/summary?language=${encodeURIComponent(language)}`;$('#questionSuggestionPanel').hidden=state.user.role==='admin_reviewer';if(state.user.role!=='admin_reviewer'){const summary=await api(summaryUrl),selected=summary.languageAvailability?.[language]||summary.totals;$('#questionMetrics').innerHTML=metrics([{label:'Publicadas',value:selected.published,note:'visíveis para toda a equipe'},{label:'Em revisão',value:selected.review,note:'somente o Revisor decide'},{label:'Sem evidência',value:summary.totals.without_evidence,note:'não utilizáveis'},{label:'Minhas sugestões',value:'—',note:'acompanhe abaixo'}]);$('#questions').innerHTML='<p class="notice"><strong>Área de consulta.</strong> As questões publicadas pelo Revisor estão nos questionários e simulados. Aqui você pode sugerir uma questão nova; somente o Revisor Demo pode editar, aprovar ou publicar.</p>';await loadMyQuestionSuggestions();return;}const status=$('#questionStatus').value,category=$('#questionCategory').value,difficulty=$('#questionDifficulty').value;const params=new URLSearchParams({status,category,difficulty,language}),[summary,rows]=await Promise.all([api(summaryUrl),api(`/api/v2/questions?${params}`)]),selected=summary.languageAvailability?.[language]||summary.totals;$('#questionMetrics').innerHTML=metrics([{label:'Publicadas',value:selected.published,note:language==='en-US'?'em inglês':'em português'},{label:'Fila de revisão',value:selected.review,note:'decisão humana pendente'},{label:'Com evidência',value:Number(selected.published)+Number(selected.review),note:'citação validada'},{label:'Sem evidência',value:summary.totals.without_evidence,note:'bloqueadas'}]);const categories=[...new Set(summary.coverage.map(x=>x.category))];if($('#questionCategory').options.length===1)$('#questionCategory').insertAdjacentHTML('beforeend',categories.map(x=>`<option>${esc(x)}</option>`).join(''));$('#questionAvailability').innerHTML=`<strong>${language==='en-US'?'English':'Português'}:</strong> `+summary.simulationAvailability.quantities.map(x=>`<span class="tag">${x.count}: ${x.published?'publicado disponível':x.preview?'disponível em prévia':'faltam questões'}</span>`).join(' ');state.selectedQuestions.clear();$('#questions').innerHTML=rows.length?rows.map(x=>{const source=x.sources?.[0];return`<article class="question review-card" data-id="${x.id}"><div class="panel-head"><label><input class="question-select" type="checkbox" value="${x.id}"> Selecionar</label><span class="pill ${source?'good':''}">${esc(x.status)}</span></div><div class="review-layout"><form class="question-editor"><label>Enunciado<textarea name="prompt" rows="4">${esc(x.prompt)}</textarea></label><fieldset class="option-editor"><legend>Alternativas</legend>${x.options.map((option,index)=>`<label class="option-row"><span class="option-letter">${String.fromCharCode(65+index)}</span><textarea name="option" rows="3" aria-label="Alternativa ${String.fromCharCode(65+index)}">${esc(option)}</textarea></label>`).join('')}</fieldset><div class="row"><label>Resposta correta<select name="correctAnswer">${x.options.map((_,index)=>`<option value="${index}" ${Number(x.correct_answer)===index?'selected':''}>Alternativa ${String.fromCharCode(65+index)}</option>`).join('')}</select></label><label>Categoria<input name="category" value="${esc(x.category)}"></label><label>Dificuldade<select name="difficulty"><option ${x.difficulty==='fácil'?'selected':''}>fácil</option><option ${x.difficulty==='intermediária'?'selected':''}>intermediária</option><option ${x.difficulty==='difícil'?'selected':''}>difícil</option></select></label></div><label>Explicação<textarea name="explanation" rows="4">${esc(x.explanation)}</textarea></label><input type="hidden" name="format" value="${esc(x.format)}"><button class="ghost">Salvar edição</button></form><aside class="source-evidence"><span class="eyebrow">EVIDÊNCIA</span>${source?`<h3>${esc(source.title)}</h3><p>${esc(source.version||'sem versão')} · ${source.page?`página ${source.page}`:esc(source.section||'seção')}</p><blockquote>${esc(source.excerpt)}</blockquote><small>${esc(source.sourceType)} · consultado em ${date(source.consultedAt)}</small>`:'<div class="danger-note">Resposta sem evidência: aprovação bloqueada.</div>'}<div class="row"><button class="ghost review-one" data-decision="approved">Aprovar</button><button class="primary review-one" data-decision="published">Publicar</button><button class="ghost review-one" data-decision="rejected">Rejeitar</button></div></aside></div></article>`}).join(''):`<div class="notice"><strong>Nenhuma questão neste filtro.</strong><p>Altere status, categoria ou dificuldade. A importação continua visível no painel Documentações.</p></div>`;$$('.question-select').forEach(x=>x.onchange=()=>x.checked?state.selectedQuestions.add(x.value):state.selectedQuestions.delete(x.value));$$('.question-editor').forEach(f=>f.onsubmit=saveQuestionEdit);$$('.review-one').forEach(b=>b.onclick=()=>reviewQuestions([b.closest('.question').dataset.id],b.dataset.decision));}

async function loadMyQuestionSuggestions(){if(!state.certifications.length)state.certifications=await api('/api/certifications');$('#suggestionCertification').innerHTML=state.certifications.map(item=>`<option value="${esc(item.code)}">${esc(item.code)} · ${esc(item.short_title)}</option>`).join('');if(state.activeCertification)$('#suggestionCertification').value=state.activeCertification.code;const rows=await api('/api/v2/question-suggestions');$('#myQuestionSuggestions').innerHTML=rows.length?rows.map(row=>`<article class="suggestion-row"><div><span class="eyebrow">${esc(row.certification_code||'SEM CERTIFICAÇÃO')} · ${esc(row.category||'GERAL')}</span><strong>${esc(row.prompt)}</strong><small>Enviada em ${date(row.created_at)}</small></div><span class="pill ${row.status==='accepted'?'good':row.status==='rejected'?'bad':''}">${esc(row.status)}</span></article>`).join(''):'<p class="empty">Você ainda não enviou sugestões.</p>';}
async function submitQuestionSuggestion(event){event.preventDefault();const values=formJson(event.currentTarget),options=String(values.options||'').split(/\r?\n/).map(item=>item.trim()).filter(Boolean);if(options.length!==4)return toast('Informe exatamente quatro alternativas, uma por linha.');await api('/api/v2/question-suggestions',{method:'POST',body:JSON.stringify({...values,options})});event.currentTarget.reset();toast('Sugestão enviada ao Revisor Demo.');await loadMyQuestionSuggestions();}
async function saveQuestionEdit(event){event.preventDefault();const card=event.currentTarget.closest('.question'),x=formJson(event.currentTarget),options=[...event.currentTarget.querySelectorAll('[name="option"]')].map(field=>field.value.trim()).filter(Boolean),correctField=event.currentTarget.querySelector('[name="correctAnswer"]'),correctAnswer=correctField.multiple?[...correctField.selectedOptions].map(option=>Number(option.value)):Number(correctField.value);await api(`/api/v2/questions/${card.dataset.id}`,{method:'PATCH',body:JSON.stringify({prompt:x.prompt,options,correctAnswer,explanation:x.explanation,distractorExplanations:[],category:x.category,difficulty:x.difficulty,format:x.format,language:state.user.questionLanguage||'pt-BR'})});toast('Edição salva com nova versão editorial.');loadQuestions();}
async function reviewQuestions(ids,decision){if(!ids.length)return toast('Selecione ao menos uma questão.');await api('/api/v2/questions/bulk-review',{method:'POST',body:JSON.stringify({ids,decision,comment:'Validação humana pela interface editorial.'})});toast(`${ids.length} questão(ões): ${decision}.`);loadQuestions();}
function prepareSimulation(event){
  event.preventDefault();
  const mode=$('#simMode').value,domain=$('#simDomain').value,language=$('#simLanguage').value;
  if(mode==='domain'&&!domain)return toast('Escolha o domínio que deseja praticar.');
  state.pendingSimulationMode=mode;
  state.pendingSimulationDomain=mode==='domain'?domain:'';
  state.pendingSimulationLanguage=language;
  navigate('simulation-confirm');
}
function renderSimulationConfirmation(){
  const mode=state.pendingSimulationMode,config=simulationModeConfig[mode],eligibility=state.simulationEligibility;
  if(!config||!eligibility?.certification){navigate('simulations');return;}
  const available=eligibility.available.published,language=state.pendingSimulationLanguage||'pt-BR',selectedDomain=mode==='domain'?state.pendingSimulationDomain:'';
  const domainAvailability=selectedDomain?eligibility.available.domains?.find(row=>row.category===selectedDomain):null;
  const blocked=state.simulation?.status==='active'||available<config.count||
    (mode==='full'&&Boolean(eligibility.used))||
    (mode==='error_review'&&Number(eligibility.available.missed||0)<config.count)||
    (mode==='domain'&&(!selectedDomain||Number(domainAvailability?.count||0)<config.count));
  const reason=state.simulation?.status==='active'?'Conclua ou retome sua tentativa em andamento.':
    available<config.count?`Há ${available} questões disponíveis no idioma selecionado; este modo requer ${config.count}.`:
    mode==='full'&&eligibility.used?'O simulado completo desta semana já foi iniciado.':
    mode==='error_review'?'Este modo requer 10 questões erradas em tentativas anteriores.':
    mode==='domain'&&!selectedDomain?'Escolha um domínio antes de continuar.':
    mode==='domain'?`O domínio “${selectedDomain}” não tem ${config.count} questões disponíveis neste idioma.`:'';
  const selection=mode==='domain'?selectedDomain:config.selection;
  $('#simulationConfirmation').innerHTML=`<p class="simulation-confirm-intro">${esc(config.description)}</p><dl class="simulation-facts"><div><dt>Certificação</dt><dd>${esc(eligibility.certification.code)} · ${esc(eligibility.certification.title)}</dd></div><div><dt>Questões</dt><dd>${config.count}</dd></div><div><dt>Tempo</dt><dd>${config.duration} minutos</dd></div><div><dt>Idioma</dt><dd>${language==='en-US'?'Inglês':'Português'}</dd></div><div><dt>Seleção</dt><dd>${esc(selection)}</dd></div></dl><p class="notice">O cronômetro começa apenas ao clicar em <strong>Confirmar e iniciar</strong>. Depois disso, a tentativa fica salva no servidor; sair da tela não pausa o tempo.${mode==='full'?' Esta ação consome a tentativa semanal.':''}</p>${blocked?`<p class="notice bad" role="alert">${esc(reason)}</p>`:''}`;
  $('#confirmSimulationStart').disabled=blocked;
}
async function confirmSimulationStart(){
  const button=$('#confirmSimulationStart'),mode=state.pendingSimulationMode;
  if(!simulationModeConfig[mode])return navigate('simulations');
  button.disabled=true;
  try{
    const created=await api('/api/v2/simulations',{method:'POST',body:JSON.stringify({mode,language:state.pendingSimulationLanguage||'pt-BR',certificationCode:state.simulationEligibility.certification.code,...(mode==='domain'?{domain:state.pendingSimulationDomain}:{})})});
    state.simulation=await api(`/api/v2/simulations/${created.id}`);
    state.simulation.index=0;
    navigate('simulation-session');
  }catch(error){toast(error.message);button.disabled=false;}
}
async function loadSimulationSession(){
  const id=state.simulation?.status==='active'?state.simulation.id:null;
  const sim=await api(id?`/api/v2/simulations/${id}`:'/api/v2/simulations/active');
  if(!sim?.id||sim.status!=='active'){navigate('simulations');return;}
  const previous=state.simulation;
  state.simulation=sim;
  sim.index=previous?.id===sim.id&&Number.isInteger(previous.index)?previous.index:Math.max(0,Math.min(sim.questions.length-1,Number(sim.current_position||1)-1));
  $('#simulationSessionTitle').textContent=`${sim.question_count} questões · ${sim.duration_minutes} minutos`;
  renderSimulation();
}
async function loadSimulationResult(){
  if($('#simulationResult').innerHTML.trim())return;
  const reports=await api('/api/v2/simulations/reports');
  if(!reports.length){navigate('simulations');return;}
  displaySimulationReport(await api(`/api/v2/simulations/${reports[0].id}/report`));
}
const simulationRemaining=sim=>sim.deadline_at?Math.max(0,Math.ceil((new Date(sim.deadline_at).getTime()-Date.now())/1000)):Math.max(0,Number(sim.remaining_seconds||0));
const simulationClock=seconds=>`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;
function renderSimulation(){
  clearInterval(state.simTimer);
  const sim=state.simulation,box=$('#simulationPlayer');
  if(!sim||state.view!=='simulation-session')return;
  if(!Number.isInteger(sim.index))sim.index=Math.max(0,Math.min(sim.questions.length-1,Number(sim.current_position||1)-1));
  const q=sim.questions[sim.index];if(!q)return;
  const saved=q.answer!==null&&q.answer!==undefined,multiple=Number(q.correct_count)>1||q.format==='multiple_response';
  const savedAnswers=saved?(Array.isArray(q.answer)?q.answer.map(Number):[Number(q.answer)]):[];
  box.innerHTML=`<article class="panel simulation-shell"><div class="panel-head"><span class="eyebrow">QUESTÃO ${sim.index+1}/${sim.questions.length} · ${esc(q.category)} · ${esc(q.difficulty)}</span><strong id="simTimer" role="timer">${simulationClock(simulationRemaining(sim))}</strong></div><div class="question-nav" aria-label="Navegar entre questões">${sim.questions.map((x,i)=>`<button type="button" class="${i===sim.index?'active':''}${x.answer!==null&&x.answer!==undefined?' answered':''}" data-index="${i}" aria-label="Questão ${i+1}${x.answer!==null&&x.answer!==undefined?', respondida':''}" ${i===sim.index?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><h2>${esc(q.prompt)}</h2>${multiple?`<p class="notice">Selecione ${q.correct_count} respostas.</p>`:''}<form id="answerForm">${q.options.map((answer,i)=>`<label class="answer"><input type="${multiple?'checkbox':'radio'}" name="answer" value="${i}" ${savedAnswers.includes(i)?'checked':''} ${multiple?'':'required'}><span>${esc(answer)}</span></label>`).join('')}<div class="simulation-answer-tools"><label>Confiança<select name="confidence"><option value="1" ${Number(q.confidence)===1?'selected':''}>1 — baixa</option><option value="3" ${!q.confidence||Number(q.confidence)===3?'selected':''}>3 — média</option><option value="5" ${Number(q.confidence)===5?'selected':''}>5 — alta</option></select></label><label class="simulation-review"><input name="marked" type="checkbox" ${q.marked_for_review?'checked':''}> Marcar para revisão</label></div><button type="submit" class="primary">${saved?'Atualizar resposta':'Salvar resposta'}</button></form><div id="feedback" role="status"></div><div class="simulation-actions"><button id="prevQuestion" class="ghost" type="button" ${sim.index===0?'disabled':''}>Anterior</button><button id="nextQuestion" class="ghost" type="button" ${sim.index===sim.questions.length-1?'disabled':''}>Próxima</button><button id="finishSim" class="primary" type="button">Entregar tentativa</button></div></article>`;
  state.simTimer=setInterval(()=>{const remaining=simulationRemaining(sim),timer=$('#simTimer');if(timer)timer.textContent=simulationClock(remaining);if(!remaining){clearInterval(state.simTimer);finishSimulation(true).catch(error=>toast(error.message));}},1000);
  $$('.question-nav button').forEach(button=>button.onclick=()=>{sim.index=Number(button.dataset.index);renderSimulation();});
  $('#prevQuestion').onclick=()=>{sim.index--;renderSimulation();};
  $('#nextQuestion').onclick=()=>{sim.index++;renderSimulation();};
  $('#finishSim').onclick=()=>finishSimulation(false).catch(error=>toast(error.message));
  const started=Date.now(),answeredIndex=sim.index;
  $('#answerForm').onsubmit=async event=>{
    event.preventDefault();const form=event.currentTarget,submit=form.querySelector('button[type="submit"]');
    const selected=[...form.querySelectorAll('[name="answer"]:checked')].map(input=>Number(input.value));
    if(multiple&&selected.length!==Number(q.correct_count))return toast(`Selecione exatamente ${q.correct_count} respostas.`);
    submit.disabled=true;
    const values=formJson(form),answer=multiple?selected:selected[0];
    try{
      const result=await api(`/api/v2/simulations/${sim.id}/autosave`,{method:'PUT',body:JSON.stringify({questionId:q.id,answer,position:answeredIndex+1,elapsedSeconds:Math.round((Date.now()-started)/1000),confidence:Number(values.confidence),marked:values.marked==='on'})});
      q.answer=answer;q.confidence=Number(values.confidence);q.marked_for_review=values.marked==='on';
      if(state.simulation?.id===sim.id&&state.simulation.questions[answeredIndex])Object.assign(state.simulation.questions[answeredIndex],{answer,confidence:Number(values.confidence),marked_for_review:values.marked==='on'});
      $('#feedback').innerHTML=result.explanation?`<div class="notice"><strong>${result.correct?'Correto':'Revisar'}</strong><p>${esc(result.explanation)}</p></div>`:'<div class="notice">Resposta salva no servidor.</div>';
      if(answeredIndex<sim.questions.length-1)setTimeout(()=>{if(state.view==='simulation-session'&&state.simulation?.id===sim.id){const current=Number.isInteger(state.simulation.index)?state.simulation.index:Math.max(0,Number(state.simulation.current_position||1)-1);if(current===answeredIndex){state.simulation.index=answeredIndex+1;renderSimulation();}}},650);
      else submit.disabled=false;
    }catch(error){submit.disabled=false;toast(error.message);}
  };
}
async function finishSimulation(automatic=false){
  if(!state.simulation||state.submittingSimulation)return;
  const answered=state.simulation.questions.filter(question=>question.answer!==null&&question.answer!==undefined).length;
  if(!automatic&&!window.confirm(`Entregar agora? ${answered} de ${state.simulation.questions.length} questão(ões) estão respondidas.`))return;
  state.submittingSimulation=true;
  try{
    const result=await api(`/api/v2/simulations/${state.simulation.id}/submit`,{method:'POST',body:'{}'});
    clearInterval(state.simTimer);
    displaySimulationReport(result);
    state.simulation=null;
    navigate('simulation-result');
  }finally{state.submittingSimulation=false;}
}
async function loadQueries(){const data=await cachedApi('queries','/api/queries'),attempts=Number(data.stats.attempts||0),correct=Number(data.stats.correct||0);$('#queryMetrics').innerHTML=metrics([{label:'Lições',value:data.lessons.length,note:'do básico ao troubleshooting'},{label:'Exercícios',value:data.exercises.length,note:'leitura, correção e construção'},{label:'Precisão',value:`${attempts?Math.round(correct/attempts*100):0}%`,note:`${correct}/${attempts} acertos`},{label:'Telemetrias',value:data.telemetry.length,note:'mapeadas aos labs'}]);$('#queryLessons').innerHTML=data.lessons.map(x=>`<details class="query-lesson"><summary><strong>${esc(x.code)} · ${esc(x.title)}</strong><span class="tag">${esc(x.level)}</span></summary><p>${esc(x.body)}</p><a href="${esc(x.source_url)}" target="_blank" rel="noopener">Documentação oficial ↗</a></details>`).join('');$('#queryMap').innerHTML=data.telemetry.map(x=>`<details class="telemetry-card"><summary><strong>${esc(x.code)} · ${esc(x.title)}</strong><span class="tag">${esc(x.lab_code||'Lab relacionado')}</span></summary><p><strong>Marcador inerte:</strong> <code>${esc(x.marker)}</code></p><p><strong>Foco:</strong> ${esc(x.focus)}</p><pre><code>${esc(x.query_template)}</code></pre><p class="muted">Use placeholders até confirmar campos e parser no tenant. Tentativas: ${x.attempts||0} · evento: ${x.events_found?'sim':'não registrado'} · query: ${x.query_correct?'validada':'pendente'}.</p></details>`).join('');$('#queryExercises').innerHTML=data.exercises.map(x=>`<article class="panel query-exercise" data-id="${x.id}"><span class="eyebrow">${esc(x.code)} · ${esc(x.exercise_type)} · ${esc(x.domain)}</span><h3>${esc(x.prompt)}</h3><form>${x.options.map((v,i)=>`<label class="answer"><input type="radio" name="answer" value="${i}" required> ${esc(v)}</label>`).join('')}<button class="primary">Responder</button></form><div class="query-feedback"></div><small>${x.attempts||0} tentativa(s), ${x.correct_attempts||0} correta(s)</small></article>`).join('');$$('.query-exercise form').forEach(form=>{form.onsubmit=answerQuery;});}
async function answerQuery(event){event.preventDefault();const card=event.currentTarget.closest('.query-exercise'),answer=Number(new FormData(event.currentTarget).get('answer')),started=Number(card.dataset.started||Date.now());const result=await api(`/api/queries/${card.dataset.id}/answer`,{method:'POST',body:JSON.stringify({selectedAnswer:answer,elapsedSeconds:Math.max(0,Math.round((Date.now()-started)/1000))})});card.querySelector('.query-feedback').innerHTML=`<div class="notice ${result.correct?'good':'bad'}"><strong>${result.correct?'Correto':'Revisar'}</strong><p>${esc(result.explanation)}</p><a href="${esc(result.sourceUrl)}" target="_blank" rel="noopener">Fonte oficial ↗</a></div>`;event.currentTarget.querySelectorAll('input,button').forEach(x=>x.disabled=true);}
function labRows(){const search=$('#labSearch').value.trim().toLowerCase(),status=$('#labStatus').value,certification=$('#labCertification').value,language=$('#labLanguage').value,source=$('#labSource').value;return state.labs.filter(x=>{const haystack=`${x.code} ${x.title} ${x.domain} ${x.category} ${x.objective} ${(x.reference_topics||[]).join(' ')} ${(x.fixture_files||[]).join(' ')}`.toLowerCase();return(!search||haystack.includes(search))&&(!certification||x.certification_code===certification)&&(!language||x.content_language===language)&&(!source||(source==='certification'&&x.source_package)||(source==='legacy'&&!x.source_package))&&(!status||(status==='completed'&&Number(x.completed_runs)>0)||(status==='cleanup'&&x.cleanup_pending)||(status==='pending'&&!Number(x.completed_runs)));});}
function renderLabs(){const rows=labRows(),runs=rows.reduce((n,x)=>n+Number(x.completed_runs||0),0),minutes=rows.reduce((n,x)=>n+Number(x.estimated_minutes||0),0),fixtures=new Set(rows.flatMap(x=>x.fixture_files||[])).size,pending=rows.filter(x=>x.cleanup_pending).length;$('#labMetrics').innerHTML=metrics([{label:'Labs no recorte',value:rows.length,note:`${rows.filter(x=>x.source_package).length} do caderno de certificações`},{label:'Carga estimada',value:`${Math.floor(minutes/60)}h${String(minutes%60).padStart(2,'0')}`,note:'somente labs com duração informada'},{label:'Fixtures relacionadas',value:fixtures,note:'dados sintéticos para prática offline'},{label:'Execuções concluídas',value:runs,note:`${pending} limpeza(s) pendente(s)`}]);$('#labs').innerHTML=rows.map(x=>{const certification=x.certification_code||'Trilha segura',isEnglish=x.content_language==='en-US';return`<details class="lab"><summary><span><span class="eyebrow">${esc(x.code)} · ${esc(certification)} · ${esc(x.difficulty)}${x.estimated_minutes?` · ${x.estimated_minutes} MIN`:''}</span><h3>${esc(x.title)}</h3><span class="tag">${isEnglish?'English':'Português'}</span>${x.source_package?'<span class="tag">Caderno 2026</span>':'<span class="tag">Lab legado preservado</span>'}</span><span class="pill ${Number(x.completed_runs)>0?'good':''}">${Number(x.completed_runs)>0?'Concluído':'Seguro'}</span></summary><div class="lab-detail-grid"><section><h4>Objetivo</h4><p>${esc(x.objective)}</p><h4>Autorização e ambiente isolado</h4><p>${esc(x.authorization_note||x.authorization)} ${esc(x.isolated_environment)}</p><h4>Pré-requisitos</h4><ol>${(x.prerequisites||[]).map(v=>`<li>${esc(v)}</li>`).join('')}</ol>${(x.fixture_files||[]).length?`<h4>Fixtures sintéticas</h4><div class="course-topics">${x.fixture_files.map(v=>`<span class="tag">${esc(v)}</span>`).join('')}</div>`:''}<h4>Etapas</h4><ol>${(x.steps||[]).map(v=>`<li>${esc(v)}</li>`).join('')}</ol></section><section>${(x.reference_topics||[]).length?`<h4>Referências de estudo</h4><ul>${x.reference_topics.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:''}${(x.validation_queries||[]).length?`<h4>Query de validação</h4>${x.validation_queries.map(v=>`<pre><code>${esc(v)}</code></pre>`).join('')}`:''}<h4>Resultado esperado</h4><p>${esc(x.expected_result)}</p><h4>Evidência</h4><p>${esc(x.evidence_requirements||'Registre somente evidência sanitizada.')}</p>${x.console_extension?`<h4>Extensão opcional no console autorizado</h4><p>${esc(x.console_extension)}</p>`:''}${(x.rubric||[]).length?`<h4>Rubrica (1 ponto por item)</h4><ul>${x.rubric.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:''}<h4>Risco e critérios de interrupção</h4><p>${esc(x.risks)}</p><p><strong>${esc(x.stop_criteria)}</strong></p><h4>Limpeza e rollback</h4><p>${esc(x.cleanup)} ${esc(x.rollback)}</p></section></div>${(x.telemetryTests||[]).length?`<h4>Testes benignos relacionados</h4>${x.telemetryTests.map(t=>`<details class="telemetry-card"><summary>${esc(t.code)} · ${esc(t.title)}</summary><p><strong>Pré-requisitos:</strong> ${(t.prerequisites||[]).map(esc).join('; ')}</p><pre><code>${(t.commands||[]).map(esc).join('\n')}</code></pre><p><strong>Esperado:</strong> ${esc(t.expected_result)}</p><p><strong>Evidência:</strong> ${esc(t.expected_evidence)}</p><p><strong>Risco/interrupção:</strong> ${esc(t.risk)} ${esc(t.stop_criteria)}</p><p><strong>Rollback:</strong> ${esc(t.rollback)}</p><pre><code>${esc(t.query_template)}</code></pre><p><strong>Script:</strong> <code>${esc(t.script_path||'documentado na interface')}</code> — executar somente na VM autorizada, manualmente e primeiro com <code>--dry-run</code>.</p></details>`).join('')}`:''}<form class="run-controls" data-id="${x.id}"><label>Status<select name="status"><option value="completed">Concluído</option><option value="in_progress">Em andamento</option><option value="interrupted">Interrompido</option></select></label><label><input type="checkbox" name="eventsFound"> Eventos encontrados</label><label><input type="checkbox" name="queryCorrect"> Query correta</label><label><input type="checkbox" name="cleanupCompleted"> Limpeza concluída</label><label>Pontuação<input name="score" type="number" min="0" max="100" value="100"></label><label>Observação sanitizada<input name="observations" maxlength="4000" placeholder="Sem CID, host, IP, usuário ou token"></label><button class="primary">Registrar execução</button></form></details>`;}).join('')||'<p class="empty">Nenhum lab corresponde ao filtro.</p>';$$('.run-controls').forEach(f=>f.onsubmit=recordLabRun);}
async function loadLabs(){state.labs=await cachedApi('labs','/api/labs');const certifications=[...new Set(state.labs.map(x=>x.certification_code).filter(Boolean))];$('#labCertification').innerHTML='<option value="">Todas as certificações</option>'+certifications.map(code=>`<option value="${esc(code)}">${esc(code)}</option>`).join('');if(state.activeCertification&&certifications.includes(state.activeCertification.code))$('#labCertification').value=state.activeCertification.code;renderLabs();}
async function recordLabRun(event){event.preventDefault();const f=event.currentTarget,x=formJson(f);await api(`/api/labs/${f.dataset.id}/run`,{method:'POST',body:JSON.stringify({status:x.status,eventsFound:x.eventsFound==='on',queryCorrect:x.queryCorrect==='on',cleanupStatus:x.cleanupCompleted==='on'?'completed':'pending',score:Number(x.score),observations:x.observations})});toast('Execução, pontuação e limpeza registradas no banco.');loadLabs();}
async function loadGoals(){
  const data=await cachedApi('goal','/api/goals/current')||{},goal=data.goal,slots=data.availability||[],days=data.exceptions||[];
  const sim=data.simulationDate||null,planned=Number(data.scheduleStats?.planned_events||0);
  $('#goalMetrics').innerHTML=metrics([{label:'Certificação',value:data.certification?.code||state.activeCertification?.code||'Escolha no topo',note:goal?'meta ativa':'sem meta'},{label:'Data final',value:goal?date(goal.target_date):'—',note:goal?'prazo da meta':'defina o prazo'},{label:goal&&data.simulationDateSuggested?'Simulado sugerido':'Simulado planejado',value:sim?date(sim):'A definir',note:'não inicia a tentativa'},{label:'Estudo semanal',value:goal?`${goal.weekly_minutes} min`:'—',note:`${planned} sessão(ões) no plano atual`}]);
  $('#goalCurrent').innerHTML=goal?`<div class="goal-deadline"><span>DATA FINAL</span><strong>${date(goal.target_date)}</strong><small>${esc(data.certification?.code||'')} · versão ${goal.version}</small></div><dl><dt>Simulado de prática</dt><dd>${sim?`${date(sim)}${data.simulationDateSuggested?' (sugestão)':''}`:'A definir'}</dd><dt>Precisão desejada</dt><dd>${goal.target_score}%</dd><dt>Limite semanal</dt><dd>${goal.weekly_minutes} min</dd><dt>Dias de estudo</dt><dd>${[...new Set(slots.map(x=>['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'][x.weekday]))].join(', ')||'—'}</dd><dt>Revisão final</dt><dd>${goal.final_review_days} dias</dd><dt>Agenda</dt><dd>${planned?`${planned} atividade(s) planejada(s)`:'Prévia ainda não aplicada'}</dd></dl><button class="ghost" data-go="calendar">Abrir calendário →</button>`:`<div class="notice">${data.certification?`Ainda não há meta para ${esc(data.certification.code)}. Preencha o formulário à esquerda ou selecione outra certificação no topo.`:'Selecione uma certificação no topo para criar a meta.'}</div>`;
  if(!goal){const form=$('#goalForm');if(state.goalFormCert!==data.certification?.code){form.reset();form.elements.title.value=data.certification?`Certificação ${data.certification.code}`:'Meta de certificação';form.elements.title.dataset.customTitle='';state.goalFormCert=data.certification?.code||'';}return;}
  state.goalFormCert=data.certification?.code||'';
  const form=$('#goalForm');form.elements.title.value=goal.title;form.elements.targetDate.value=String(goal.target_date).slice(0,10);form.elements.plannedSimulationDate.value=goal.planned_simulation_date?String(goal.planned_simulation_date).slice(0,10):'';
  form.elements.targetScore.value=goal.target_score;form.elements.weeklyMinutes.value=goal.weekly_minutes;form.elements.finalReviewDays.value=goal.final_review_days;
  form.elements.freeDates.value=days.filter(x=>!x.available).map(x=>String(x.exception_date).slice(0,10)).join(', ');
  const first=slots[0];if(first){form.elements.startTime.value=String(first.start_time).slice(0,5);form.elements.endTime.value=String(first.end_time).slice(0,5);form.elements.sessionMinutes.value=first.session_minutes;}
  const weekdays=new Set(slots.map(x=>Number(x.weekday)));$$('#goalWeekdays input').forEach(x=>x.checked=weekdays.has(Number(x.value)));
  form.elements.maxDailyMinutes.value=goal.max_daily_minutes;form.elements.minSessionMinutes.value=goal.min_session_minutes;form.elements.maxSessionMinutes.value=goal.max_session_minutes;form.elements.gapMinutes.value=goal.session_gap_minutes;form.elements.intensity.value=goal.intensity;
}
async function saveGoal(event){
  event.preventDefault();
  const x=formJson(event.currentTarget);
  const weekdays=$$('#goalWeekdays input:checked').map(input=>Number(input.value));
  if(!weekdays.length)return toast('Selecione pelo menos um dia disponível.');
  const availability=weekdays.map(weekday=>({weekday,startTime:x.startTime,endTime:x.endTime,sessionMinutes:Number(x.sessionMinutes),label:'Janela principal'}));
  if(x.secondWindowEnabled==='on')for(const weekday of weekdays)availability.push({weekday,startTime:x.secondStartTime,endTime:x.secondEndTime,sessionMinutes:Number(x.sessionMinutes),label:'Segunda janela'});
  const freeDates=String(x.freeDates||'').split(',').map(value=>value.trim()).filter(Boolean);
  await api('/api/goals',{method:'POST',body:JSON.stringify({
    title:x.title,targetDate:x.targetDate,plannedSimulationDate:x.plannedSimulationDate||undefined,targetScore:Number(x.targetScore),weeklyMinutes:Number(x.weeklyMinutes),
    finalReviewDays:Number(x.finalReviewDays),availability,freeDates,
    minSessionMinutes:Number(x.minSessionMinutes),maxSessionMinutes:Number(x.maxSessionMinutes),
    maxDailyMinutes:Number(x.maxDailyMinutes),maxWeeklyMinutes:Number(x.weeklyMinutes),
    preferredPeriod:x.preferredPeriod,gapMinutes:Number(x.gapMinutes),intensity:x.intensity,
    weekendsEnabled:weekdays.some(day=>day===0||day===6)
  })});
  toast('Nova versão flexível da meta salva; o histórico anterior foi preservado.');
  await loadGoals();
  navigate('calendar');
  await previewPlan();
}
async function recalculate(){navigate('calendar');return previewPlan();}
function renderEvents(rows,selector){const box=$(selector);box.innerHTML=rows?.length?rows.map(x=>`<article class="event"><strong>${esc(x.title||x.notes)}</strong><div class="muted">${date(x.planned_start)} · ${esc(x.activity_type||'atividade')} · ${Number(x.planned_minutes||0)} min</div></article>`).join(''):'<p class="empty">Nenhuma sessão planejada.</p>';}
const localDay=value=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
const addDays=(value,n)=>{const d=new Date(value);d.setDate(d.getDate()+n);return d;};
const dayIso=value=>`${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}-${String(value.getDate()).padStart(2,'0')}`;
function calendarBounds(){const a=new Date(state.calendarAnchor),view=state.calendarView;if(view==='day')return{from:dayIso(a),to:dayIso(a),label:new Intl.DateTimeFormat('pt-BR',{dateStyle:'full'}).format(a)};if(view==='week'){const start=addDays(a,-a.getDay()),end=addDays(start,6);return{from:dayIso(start),to:dayIso(end),label:`${date(start)} — ${date(end)}`};}if(view==='agenda'||view==='pending'){const start=new Date(),end=addDays(start,90);return{from:dayIso(start),to:dayIso(end),label:view==='pending'?'Pendências':'Próximos 90 dias'};}const start=new Date(a.getFullYear(),a.getMonth(),1),end=new Date(a.getFullYear(),a.getMonth()+1,0);return{from:dayIso(start),to:dayIso(end),label:new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(a)};}
function eventCard(x){
  const type=x.activities?.[0]?.type||x.activity_type||'document',start=new Date(x.planned_start),duration=Math.round((new Date(x.planned_end)-start)/60000);
  const time=new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}).format(start);
  if(x.kind)return `<div class="calendar-milestone ${esc(type)}" aria-label="${esc(x.title)}, ${date(x.planned_start)}"><span>${x.kind==='goal_target'?'PRAZO FINAL':x.kind==='simulation_plan'?'SIMULADO PLANEJADO':'SIMULADO CONCLUÍDO'} · ${time}</span><strong>${esc(x.title)}</strong><small>${x.kind==='simulation_plan'?'Planejamento; não inicia uma tentativa':x.kind==='goal_target'?'Data final da meta':'Resultado registrado'}${x.kind==='simulation_plan'?` · ${duration} min`:''}</small></div>`;
  return `<button class="calendar-event ${esc(type)}" data-session="${x.id}" draggable="true" aria-label="${esc(x.title)}, ${date(x.planned_start)}"><span>${time} · ${duration} min · ${esc(type)}</span><strong>${esc(x.title)}</strong><small>${esc(x.status)} · esforço ${x.planned_minutes} min</small></button>`;
}
function renderCalendar(){const box=$('#calendarEvents'),rows=state.calendarView==='pending'?state.calendarRows.filter(x=>['planned','missed'].includes(x.status)):state.calendarRows,bounds=calendarBounds();$('#calendarRange').textContent=bounds.label;if(['agenda','pending'].includes(state.calendarView)){box.className='calendar-board agenda-view';box.innerHTML=rows.length?rows.map(x=>`<article class="agenda-event"><time>${date(x.planned_start)}</time>${eventCard(x)}</article>`).join(''):'<div class="notice">Nenhuma atividade neste período. Gere uma prévia ou ajuste a disponibilidade.</div>';}
  else{const start=new Date(`${bounds.from}T12:00:00`),end=new Date(`${bounds.to}T12:00:00`),days=[];for(let d=state.calendarView==='month'?addDays(start,-start.getDay()):start;d<=(state.calendarView==='month'?addDays(end,6-end.getDay()):end);d=addDays(d,1))days.push(new Date(d));box.className=`calendar-board ${state.calendarView}-view`;box.innerHTML=`<div class="calendar-weekdays">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${days.map(d=>{const key=dayIso(d),events=rows.filter(x=>localDay(x.planned_start)===key);return`<section class="calendar-cell ${key===localDay(new Date())?'today':''}" aria-label="${date(d)}"><header><span>${d.getDate()}</span><small>${events.length?`${events.length} sessão(ões)`:''}</small></header>${events.map(eventCard).join('')}</section>`}).join('')}</div>`;}
  const cells=$$('.calendar-cell');
  if(cells.length){
    const rangeStart=new Date(`${bounds.from}T12:00:00`);
    const first=state.calendarView==='month'?addDays(rangeStart,-rangeStart.getDay()):rangeStart;
    cells.forEach((cell,index)=>{cell.dataset.date=dayIso(addDays(first,index));});
  }
  $$('.calendar-event').forEach(button=>{
    button.onclick=()=>openSession(button.dataset.session);
    button.ondragstart=event=>{event.dataTransfer.setData('text/plain',button.dataset.session);event.dataTransfer.effectAllowed='move';};
  });
  cells.forEach(cell=>{
    cell.ondragover=event=>{event.preventDefault();event.dataTransfer.dropEffect='move';cell.classList.add('drop-target');};
    cell.ondragleave=()=>cell.classList.remove('drop-target');
    cell.ondrop=async event=>{event.preventDefault();cell.classList.remove('drop-target');await moveSessionToDate(event.dataTransfer.getData('text/plain'),cell.dataset.date);};
  });
}
async function moveSessionToDate(id,targetDate){
  const row=state.calendarRows.find(item=>item.id===id);
  if(!row)return;
  if(row.locked)return toast('Desbloqueie a sessão antes de arrastar.');
  const time=new Intl.DateTimeFormat('en-GB',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(row.planned_start));
  const duration=new Date(row.planned_end)-new Date(row.planned_start);
  const start=new Date(`${targetDate}T${time}:00-03:00`);
  const end=new Date(start.getTime()+duration);
  await api(`/api/v2/calendar/sessions/${id}`,{method:'PATCH',body:JSON.stringify({plannedStart:start.toISOString(),plannedEnd:end.toISOString()})});
  toast('Sessão movida por arrastar e soltar; alteração auditada.');
  await loadCalendar();
}
async function loadCalendar(){
  const bounds=calendarBounds();$('#calendarLoading').hidden=false;
  try{
    const [rows,goalData]=await Promise.all([api(`/api/v2/calendar?from=${bounds.from}&to=${bounds.to}&scope=${$('#calendarScope').value}`),cachedApi('goal','/api/goals/current')]);
    state.calendarRows=rows;renderCalendar();
    const sessions=rows.filter(x=>!x.kind),planned=sessions.filter(x=>x.status==='planned').length,completed=sessions.filter(x=>x.status==='completed').length;
    const totalMinutes=sessions.reduce((n,x)=>n+Number(x.planned_minutes||0),0),modules=sessions.filter(x=>x.activity_type==='module').length;
    $('#calendarMetrics').innerHTML=metrics([{label:'Sessões de estudo',value:sessions.length,note:`${modules} de curso/módulo`},{label:'Carga planejada',value:`${Math.round(totalMinutes/6)/10}h`,note:`${planned} pendentes`},{label:'Concluídas',value:completed,note:'histórico preservado'},{label:'Fuso',value:'BRT',note:'America/Sao_Paulo'}]);
    const goal=goalData?.goal,sim=goalData?.simulationDate;
    $('#calendarGoalSummary').innerHTML=goal?`<div class="goal-deadline"><span>DATA FINAL · ${esc(goalData.certification?.code||'')}</span><strong>${date(goal.target_date)}</strong></div><div class="calendar-goal-facts"><span><b>Simulado:</b> ${sim?`${date(sim)}${goalData.simulationDateSuggested?' (sugestão)':''}`:'a definir'}</span><span><b>Revisão final:</b> ${goal.final_review_days} dias</span><span><b>Estudo:</b> ${goal.weekly_minutes} min/semana</span><span><b>Janelas:</b> ${goalData.availability.length}</span></div><p class="field-hint">A prévia usa o limite semanal da meta. O simulado planejado não inicia a tentativa nem ocupa sua cota semanal.</p>`:`<div class="notice">${goalData?.certification?`Ainda não há meta para ${esc(goalData.certification.code)}. Selecione outra certificação no topo ou crie uma meta.`:'Escolha uma certificação e configure a meta para gerar o calendário.'}</div>`;
  }catch(error){
    state.calendarRows=[];$('#calendarEvents').innerHTML=`<div class="notice bad"><strong>Não foi possível carregar o calendário.</strong><p>${esc(error.message)}</p><button class="ghost" id="calendarRetry">Tentar novamente</button></div>`;$('#calendarMetrics').innerHTML='';$('#calendarRetry').onclick=loadCalendar;
  }finally{$('#calendarLoading').hidden=true;}
}
async function previewPlan(){
  try{const plan=await api('/api/v2/plans/preview',{method:'POST',body:'{}'});state.planPreview=plan;$('#applyPlanBtn').disabled=!plan.feasible;
    const labels={module:'Cursos e módulos',document:'Documentos',quiz:'Questões',query:'Queries',lab:'Labs',review:'Revisão'};
    const breakdown=Object.entries(plan.activityBreakdown||{}).map(([type,count])=>`<span class="tag">${esc(labels[type]||type)}: ${count}</span>`).join('');
    $('#planPreview').innerHTML=`<div class="notice ${plan.feasible?'good':'bad'}"><strong>${plan.feasible?'Plano viável':'Capacidade insuficiente'}</strong><p>${plan.sessions.filter(x=>!x.preserved).length} sessões · ${plan.activityCount} atividades · ${Math.round(plan.requiredMinutes/60*10)/10}h necessárias · ${Math.round(plan.plannedMinutes/60*10)/10}h distribuídas.</p><div class="tags">${breakdown}</div><p>Simulado de prática: ${plan.goal?.simulationDate?date(plan.goal.simulationDate):'não definido'} · prazo final: ${date(plan.goal?.targetDate)}.</p>${plan.conflicts.slice(0,8).map(x=>`<p>${esc(x.message)}</p>`).join('')}</div>`;
    toast('Prévia gerada; o plano atual ainda não foi alterado.');
  }catch(error){$('#planPreview').innerHTML=`<div class="notice bad">${esc(error.message)}</div>`;toast(error.message);}
}
async function applyPlan(){if(!state.planPreview)return;const result=await api(`/api/v2/plans/${state.planPreview.id}/apply`,{method:'POST',body:'{}'});toast(`${result.created} sessões detalhadas aplicadas; histórico anterior preservado.`);state.planPreview=null;$('#applyPlanBtn').disabled=true;loadCalendar();}
function openSession(id){const row=state.calendarRows.find(x=>x.id===id);if(!row)return;state.currentSession=row;$('#sessionBadge').textContent=`${row.status} · ${row.planned_minutes} min`;$('#sessionTitle').textContent=row.title;$('#sessionDetails').innerHTML=`<dl><dt>Horário</dt><dd>${date(row.planned_start)} — ${date(row.planned_end)}</dd><dt>Prioridade</dt><dd>${row.priority}</dd><dt>Responsável</dt><dd>${esc(row.display_name)}</dd><dt>Bloqueada</dt><dd>${row.locked?'sim':'não'}</dd></dl>${row.activities.map((a,i)=>`<article class="session-activity"><span class="eyebrow">${i+1}. ${esc(a.type)} · ${a.minutes} MIN</span><h3>${esc(a.title)}</h3><p><strong>Objetivo:</strong> ${esc(a.objective)}</p><p>${esc(a.instructions)}</p>${a.documentId?`<p><strong>Material:</strong> ${a.page?`página ${a.page}`:esc(a.section||'seção')} · versão vinculada</p><blockquote>${esc(a.excerpt||'')}</blockquote><button class="ghost open-session-material" data-id="${a.documentId}">Abrir material</button>`:''}${a.questionCount?`<p>Questões: ${a.questionCount} · ${esc(a.questionCategory)}</p>`:''}<p><strong>Entregável:</strong> ${esc(a.deliverable||'registro de conclusão')}</p><p><strong>Critério:</strong> ${esc(a.completionCriteria)}</p>${a.curatorStatus!=='ready'?'<div class="notice">Conteúdo pendente de curadoria.</div>':''}</article>`).join('')}<div class="row"><button id="startSession" class="ghost">Iniciar estudo</button><button id="completeSession" class="primary">Concluir</button><button id="lockSession" class="ghost">${row.locked?'Desbloquear':'Bloquear'}</button></div>`;$$('.open-session-material').forEach(b=>b.onclick=()=>{$('#sessionDrawer').close();navigate('documents');setTimeout(()=>openDocument(b.dataset.id),350);});$('#startSession').onclick=()=>updateSession({status:'in_progress'});$('#completeSession').onclick=()=>updateSession({status:'completed'});$('#lockSession').onclick=()=>updateSession({locked:!row.locked});$('#sessionDrawer').showModal();}
async function updateSession(change){await api(`/api/v2/calendar/sessions/${state.currentSession.id}`,{method:'PATCH',body:JSON.stringify(change)});$('#sessionDrawer').close();toast('Sessão atualizada e auditada.');loadCalendar();}
async function syncPreview(provider){const result=await api('/api/calendar/sync-preview',{method:'POST',body:JSON.stringify({provider})});$('#syncPreview').innerHTML=`<div class="notice"><strong>${result.count} evento(s)</strong><p>${esc(result.message)}</p><button class="primary" disabled>Confirmar após configurar OAuth no backend</button></div>`;}
async function loadRanking(){const data=await api(`/api/v2/ranking?period=${state.rankingPeriod}`),roleLabel={analyst:'Usuário',manager:'Gestor',admin_reviewer:'Revisor Demo'};const me=data.rows.find(x=>x.isMe);$('#myRanking').textContent=me?`Minha posição: ${me.position}º`:'Sem posição';$('#rankingMetrics').innerHTML=metrics([{label:'Pessoas da equipe',value:data.rows.length,note:'todos os usuários ativos'},{label:'Meu XP',value:me?.xp||0,note:'separado da prontidão'},{label:'Eventos auditáveis',value:data.rows.reduce((n,x)=>n+Number(x.events),0),note:'com idempotência'},{label:'Período',value:state.rankingPeriod,note:'mesma regra para todos'}]);$('#rankingTable').innerHTML=data.rows.map(x=>{const initials=String(x.display_name||'?').split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();return`<article class="ranking-row ${x.isMe?'is-me':''}"><strong class="ranking-position">${x.position}º</strong>${x.has_photo?`<img class="ranking-avatar" src="/api/v2/users/${encodeURIComponent(x.id)}/photo" alt="Foto de ${esc(x.display_name)}">`:`<span class="ranking-avatar initials" aria-hidden="true">${esc(initials)}</span>`}<div class="ranking-person"><h3>${esc(x.display_name)}${x.isMe?' <small>Você</small>':''}</h3><small>${esc(roleLabel[x.role]||'Usuário')} · ${x.events} evento(s) válido(s)</small></div><span class="pill ${x.position<=3?'good':''}">${x.xp} XP</span></article>`;}).join('')||'<div class="notice">Nenhum usuário ativo nesta equipe.</div>';}
async function loadGlossary(){const q=$('#glossarySearch').value.trim(),rows=await cachedApi(`glossary:${q}`,`/api/glossary?q=${encodeURIComponent(q)}`);$('#glossaryCount').textContent=`${rows.length} termo(s)`;$('#glossaryGrid').innerHTML=rows.map(x=>`<article class="glossary-card"><span class="eyebrow">${esc(x.category||'Falcon')}</span><h3>${esc(x.term_pt)}</h3><strong>${esc(x.term_en)}</strong><p>${esc(x.definition)}</p>${x.source_url?`<a href="${esc(x.source_url)}" target="_blank" rel="noopener">Fonte oficial ↗</a>`:''}</article>`).join('')||'<p class="empty">Nenhum termo encontrado.</p>';}
async function loadAudit(){try{const rows=await api('/api/audit');$('#auditLog').innerHTML=`<div class="stack">${rows.slice(0,30).map(x=>`<div><strong>${esc(x.action)}</strong> · ${esc(x.entity_type||'sistema')} · ${date(x.created_at)}</div>`).join('')}</div>`;}catch(error){$('#auditLog').innerHTML=`<p class="empty">${esc(error.message)}</p>`;}}
async function loadProfile(){const profile=await api('/api/v2/profile'),form=$('#profileForm');form.elements.displayName.value=profile.display_name||'';form.elements.jobTitle.value=profile.job_title||'';form.elements.organization.value=profile.organization||'';form.elements.bio.value=profile.bio||'';$('#profileEmail').textContent=profile.email;$('#profileRole').textContent={analyst:'Usuário comum',manager:'Gerente',admin_reviewer:'Revisor Demo'}[state.user.role]||state.user.role;$('#profilePhoto').src=profile.has_photo?`/api/v2/profile/photo?v=${Date.now()}`:'data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="160" height="160"><rect width="100%" height="100%" rx="80" fill="#e8eceb"/><text x="50%" y="55%" text-anchor="middle" font-size="54" font-family="Arial" fill="#52605d">${(profile.display_name||'?').slice(0,1).toUpperCase()}</text></svg>`);}
async function saveProfile(event){event.preventDefault();const x=formJson(event.currentTarget),profile=await api('/api/v2/profile',{method:'PUT',body:JSON.stringify(x)});state.user.displayName=profile.display_name;showApp();toast('Perfil atualizado.');}
async function saveProfilePhoto(event){event.preventDefault();await api('/api/v2/profile/photo',{method:'POST',body:new FormData(event.currentTarget)});event.currentTarget.reset();await loadProfile();toast('Foto atualizada.');}
async function loadAdminPerformance(){const userId=$('#adminUser').value,certification=$('#adminCertification').value;if(!userId||!certification)return;const data=await api(`/api/v2/admin/performance?userId=${encodeURIComponent(userId)}&certification=${encodeURIComponent(certification)}`);const answers=data.domains.reduce((sum,row)=>sum+Number(row.total),0),correct=data.domains.reduce((sum,row)=>sum+Number(row.correct),0);$('#adminPerformance').innerHTML=`<div class="metrics compact">${metrics([{label:'Progresso',value:`${Math.round(Number(data.progress.percent||0))}%`},{label:'Precisão',value:`${answers?Math.round(correct/answers*100):0}%`},{label:'Documentos',value:`${data.coverage.documents_read}/${data.coverage.documents}`},{label:'Labs',value:`${data.coverage.labs_completed}/${data.coverage.labs}`}])}</div><h4>Evolução</h4><div id="adminTrend"></div><h4>Domínios</h4><div id="adminDomains"></div>`;renderAnalytics(data,'#adminTrend','#adminDomains');}
async function loadApprovalQueue(){if(!['manager','admin_reviewer'].includes(state.user.role))return;const rows=await api(`/api/v2/admin/simulation-approvals?status=${encodeURIComponent($('#approvalStatus').value)}`);$('#approvalQueue').innerHTML=rows.length?rows.map(row=>`<article class="approval-row"><div><span class="eyebrow">${esc(row.certification_code||'SEM TRILHA')} · ${esc(row.mode)}</span><h3>${esc(row.display_name)}</h3><p>${date(row.submitted_at)} · ${row.question_count} questões · ${Number(row.score||0).toFixed(1)}%</p>${row.rejection_reason?`<p class="notice bad"><strong>Motivo:</strong> ${esc(row.rejection_reason)}</p>`:''}</div><div><span class="pill ${row.approval_status==='approved'?'good':row.approval_status==='rejected'?'bad':''}">${esc(row.approval_status)}</span>${row.approval_status==='pending'?`<div class="row"><button class="ghost approval-decision" data-id="${row.id}" data-decision="rejected">Reprovar</button><button class="primary approval-decision" data-id="${row.id}" data-decision="approved">Aprovar</button></div>`:''}</div></article>`).join(''):'<p class="empty">Nenhuma prova neste estado.</p>';$$('.approval-decision').forEach(button=>button.onclick=()=>decideSimulation(button.dataset.id,button.dataset.decision));}
async function decideSimulation(id,decision){let reason;if(decision==='rejected'){reason=prompt('Informe o motivo da reprovação:');if(!reason?.trim())return;}if(!confirm(`${decision==='approved'?'Aprovar':'Reprovar'} esta prova? A decisão ficará registrada na auditoria.`))return;await api(`/api/v2/admin/simulation-approvals/${id}/decision`,{method:'POST',body:JSON.stringify({decision,reason})});toast('Decisão registrada.');await loadApprovalQueue();}
async function createAdminUser(event){event.preventDefault();const values=formJson(event.currentTarget);await api('/api/v2/admin/users',{method:'POST',body:JSON.stringify(values)});event.currentTarget.reset();toast('Usuário criado com as permissões escolhidas.');await loadAdmin();}
async function loadAdminSuggestions(){const rows=await api('/api/v2/question-suggestions');$('#adminSuggestions').innerHTML=rows.length?rows.map(row=>`<article class="suggestion-row"><div><span class="eyebrow">${esc(row.certification_code||'SEM CERTIFICAÇÃO')} · ${esc(row.category)}</span><h3>${esc(row.prompt)}</h3><p>${esc(row.display_name)} · ${date(row.created_at)}</p>${row.source_note?`<small>Fonte/observação: ${esc(row.source_note)}</small>`:''}</div><div><span class="pill ${row.status==='accepted'?'good':row.status==='rejected'?'bad':''}">${esc(row.status)}</span>${['submitted','in_review'].includes(row.status)?`<div class="row"><button class="ghost suggestion-decision" data-id="${row.id}" data-status="rejected">Rejeitar</button><button class="primary suggestion-decision" data-id="${row.id}" data-status="accepted">Aceitar para curadoria</button></div>`:''}</div></article>`).join(''):'<p class="empty">Nenhuma sugestão recebida.</p>';$$('.suggestion-decision').forEach(button=>button.onclick=async()=>{const reviewNote=button.dataset.status==='rejected'?prompt('Motivo para o usuário (opcional):')||'':prompt('Nota de curadoria (opcional):')||'';await api(`/api/v2/question-suggestions/${button.dataset.id}`,{method:'PATCH',body:JSON.stringify({status:button.dataset.status,reviewNote})});toast('Sugestão atualizada.');await loadAdminSuggestions();});}
async function loadAdmin(){try{const [users,certifications,auditRows]=await Promise.all([api('/api/v2/admin/users'),api('/api/certifications'),api('/api/audit')]),roleLabel={analyst:'Usuário comum',manager:'Gestor',admin_reviewer:'Revisor Demo'};$('#adminRoleBadge').textContent=`Seu acesso: ${roleLabel[state.user.role]}`;$('#adminUser').innerHTML=users.map(user=>`<option value="${user.id}">${esc(user.display_name)} · ${esc(roleLabel[user.role])}</option>`).join('');$('#adminCertification').innerHTML=certifications.map(item=>`<option value="${esc(item.code)}">${esc(item.code)} · ${esc(item.short_title)}</option>`).join('');if(state.activeCertification)$('#adminCertification').value=state.activeCertification.code;const reviewerOption=$('#adminNewUserRole').querySelector('[value="admin_reviewer"]');reviewerOption.hidden=state.user.role!=='admin_reviewer';if(state.user.role!=='admin_reviewer'&&$('#adminNewUserRole').value==='admin_reviewer')$('#adminNewUserRole').value='analyst';$('#adminMetrics').innerHTML=metrics([{label:'Usuários ativos',value:users.length,note:'todos visíveis no ranking'},{label:'Certificações',value:certifications.length,note:'dados separados por trilha'},{label:'Provas pendentes',value:'—',note:'decisão auditada'},{label:'Seu perfil',value:roleLabel[state.user.role],note:'permissões validadas no servidor'}]);$('#adminTeam').innerHTML=users.map(user=>{const initials=String(user.display_name||'?').split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();return`<article class="admin-team-row">${user.has_photo?`<img class="ranking-avatar" src="/api/v2/users/${encodeURIComponent(user.id)}/photo" alt="Foto de ${esc(user.display_name)}">`:`<span class="ranking-avatar initials">${esc(initials)}</span>`}<div><strong>${esc(user.display_name)}</strong><small>${esc(user.email)}</small></div><span class="pill">${esc(roleLabel[user.role])}</span></article>`;}).join('');$('#adminActivity').innerHTML=`<h3>Alterações recentes</h3><div class="activity-list">${auditRows.slice(0,10).map(row=>`<div><strong>${esc(row.action)}</strong><span>${esc(row.entity_type||'sistema')} · ${date(row.created_at)}</span></div>`).join('')||'<p class="empty">Nenhuma alteração registrada.</p>'}</div>`;$('#approvalPanel').hidden=false;$('#suggestionReviewPanel').hidden=state.user.role!=='admin_reviewer';await loadAdminPerformance();await loadApprovalQueue();if(state.user.role==='admin_reviewer')await loadAdminSuggestions();}catch(error){$('#adminMetrics').innerHTML=`<p class="notice bad">${esc(error.message)}</p>`;}}

